import type { LanguageCode } from "./country";

/**
 * - input:       exactly what the user typed (normalized)
 * - variant:     orthographic variant (plural, accents) generated by rules
 * - synonym:     alternative wording in the same language
 * - translation: equivalent term in another language
 */
export type TermKind = "input" | "variant" | "synonym" | "translation";

/** Who produced the term. Only "user" and "google-ads-ideas" are observed facts; "machine" is an automatic translation. */
export type TermSource = "user" | "rules" | "llm" | "google-ads-ideas" | "machine";

export interface ProductTerm {
  readonly term: string;
  readonly language: LanguageCode;
  readonly kind: TermKind;
  readonly source: TermSource;
}

export interface ProductQuery {
  /** Normalized key used to group analyses of the same product over time. */
  readonly canonicalKey: string;
  readonly displayName: string;
  readonly inputLanguage: LanguageCode;
  readonly terms: readonly ProductTerm[];
}
